{
  "type": "object",
  "properties": {
    "bgm": {
      "type": "string",
      "format": "file",
      "title": "闯关背景音乐",
      "description": "仅支持 MP3 格式，文件大小需小于 1M",
      "ui:options": {
        "accept": "audio/mpeg,.mp3"
      },
      "default": ""
    },
    "navColor": {
      "type": "string",
      "format": "color",
      "title": "导航栏颜色",
      "default": "#07abff"
    },
    "modules": {
      "type": "array",
      "title": "内容模块",
      "$demo": {
        "sortable": true
      },
      "items": {
        "oneOf": [
          {
            "title": "图片模块",
            "properties": {
              "type": {
                "const": "image"
              },
              "image": {
                "type": "string",
                "format": "image",
                "title": "图片",
                "accept": "image/png,image/gif"
              }
            },
            "required": [
              "type",
              "image"
            ]
          },
          {
            "title": "按钮模块",
            "properties": {
              "type": {
                "const": "button"
              },
              "image": {
                "type": "string",
                "format": "image",
                "title": "按钮图片",
                "description": "整宽展示，高度 97px（1 倍），导出 2 倍图",
                "accept": "image/png,image/jpeg"
              }
            },
            "required": [
              "type",
              "image"
            ]
          },
          {
            "title": "参与人数模块",
            "$demo": {
              "maxItems": 1
            },
            "properties": {
              "type": {
                "const": "participant"
              },
              "bgImage": {
                "type": "string",
                "format": "image",
                "title": "参与人数背景图",
                "accept": "image/png"
              },
              "count": {
                "type": "number",
                "title": "参与人数",
                "default": 0
              }
            },
            "required": [
              "type"
            ]
          },
          {
            "title": "视频模块",
            "$demo": {
              "maxItems": 1
            },
            "properties": {
              "type": {
                "const": "video"
              },
              "videoBg": {
                "type": "string",
                "format": "image",
                "title": "视频背景图",
                "accept": "image/png"
              },
              "video": {
                "type": "object",
                "title": "视频",
                "format": "video",
                "properties": {
                  "url": {
                    "type": "string",
                    "title": "视频地址"
                  },
                  "poster": {
                    "type": "string",
                    "title": "封面地址",
                    "format": "image"
                  }
                },
                "required": [
                  "url"
                ],
                "ui:options": {
                  "accept": "video/mp4,video/webm",
                  "videoPreviewStyle": "controls"
                }
              }
            },
            "required": [
              "type",
              "video"
            ]
          },
          {
            "title": "集卡抽奖模块",
            "$demo": {
              "maxItems": 1
            },
            "properties": {
              "type": {
                "const": "collectCard"
              },
              "bgImage": {
                "type": "string",
                "format": "image",
                "title": "集卡背景图",
                "description": "仅支持 png，宽 375px，高 205px，导出 2 倍图",
                "accept": "image/png"
              },
              "total": {
                "type": "number",
                "title": "卡片总数",
                "description": "进度条右侧目标值，同时决定卡片展示个数",
                "default": 4
              },
              "collected": {
                "type": "number",
                "title": "已收集数量",
                "description": "进度条左侧数值与已获得卡片个数",
                "default": 1
              },
              "obtainedImage": {
                "type": "string",
                "format": "image",
                "title": "已获得卡片图",
                "description": "单张卡片尺寸 98x100（1 倍），不配置时展示占位样式",
                "accept": "image/png,image/jpeg"
              },
              "unobtainedImage": {
                "type": "string",
                "format": "image",
                "title": "未获得卡片图",
                "description": "单张卡片尺寸 98x100（1 倍），不配置时展示占位样式",
                "accept": "image/png,image/jpeg"
              }
            },
            "required": [
              "type"
            ]
          },
          {
            "title": "关卡模块",
            "properties": {
              "type": {
                "const": "level"
              },
              "bgImage": {
                "type": "string",
                "format": "image",
                "title": "关卡背景图",
                "description": "仅支持 png，宽 375px，高度需覆盖关卡总高，导出 2 倍图，大小不超过 1024KB",
                "accept": "image/png"
              },
              "guide": {
                "type": "object",
                "format": "spine",
                "title": "闯关引导形象",
                "description": "Spine 骨骼动画素材包，尺寸 W=80px H=130px（导出两倍）",
                "properties": {
                  "kind": {
                    "const": "spine"
                  },
                  "version": {
                    "const": 1
                  },
                  "assetId": {
                    "type": "string",
                    "pattern": "^spine_[a-f0-9]{64}$"
                  }
                },
                "required": [
                  "kind",
                  "version",
                  "assetId"
                ],
                "additionalProperties": false,
                "ui:options": {
                  "accept": ".zip",
                  "group": "闯关引导形象"
                }
              },
              "levels": {
                "type": "array",
                "title": "关卡图",
                "description": "每张关卡图支持未解锁/已解锁/已完成三种图片、自由坐标定位与自定义尺寸；坐标在预览区内拖拽调整（1 倍像素），尺寸为 2 倍值；关卡仅支持添加、删除和父子层级管理",
                "$demo": {
                  "sortable": false
                },
                "ui:options": {
                  "detailPresentation": "sheet",
                  "detailBreadcrumbTitle": "关卡列表",
                  "itemTitleTemplate": "关卡 {index}"
                },
                "items": {
                  "oneOf": [
                    {
                      "title": "关卡",
                      "properties": {
                        "type": {
                          "const": "levelCard"
                        },
                    "lockedImage": {
                      "type": "string",
                      "format": "image",
                      "title": "未解锁图",
                      "accept": "image/png,image/jpeg"
                    },
                    "unlockedImage": {
                      "type": "string",
                      "format": "image",
                      "title": "已解锁图",
                      "accept": "image/png,image/jpeg"
                    },
                    "completedImage": {
                      "type": "string",
                      "format": "image",
                      "title": "已完成图",
                      "accept": "image/png,image/jpeg"
                    },
                    "animation": {
                      "type": "string",
                      "format": "file",
                      "title": "SVGA 动效",
                      "description": "动效格式 svga，循环播放，配置后优先于静态图",
                      "ui:options": {
                        "accept": ".svga"
                      }
                    },
                    "position": {
                      "type": "position",
                      "key": "levelCard",
                      "title": "自由坐标",
                      "description": "在预览区内拖拽定位关卡图（1 倍像素，相对背景图）",
                      "size": {
                        "width": 375,
                        "height": 656
                      },
                      "default": {
                        "x": 14,
                        "y": 1
                      }
                    },
                    "w": {
                      "type": "number",
                      "title": "W"
                    },
                    "h": {
                      "type": "number",
                      "title": "H"
                    }
                  },
                  "required": [
                    "type"
                  ]
                }
                ]
              }
              }
            },
            "required": [
              "type"
            ]
          }
        ]
      },
      "default": [
        {
          "type": "image",
          "image": "https://img.onlywnn.cn/figma/h_c61916f5.png"
        },
        {
          "type": "participant",
          "bgImage": "https://img.onlywnn.cn/figma/h_19dbcc85.png",
          "count": 128
        },
        {
          "type": "video",
          "videoBg": "",
          "video": {
            "url": "",
            "poster": ""
          }
        },
        {
          "type": "level",
          "bgImage": "https://img.onlywnn.cn/figma/h_6e2a6768.png",
          "levels": [
            {
              "type": "levelCard",
              "unlockedImage": "https://img.onlywnn.cn/figma/h_e589fc90.png",
              "position": {
                "x": 14,
                "y": 1
              },
              "w": 330,
              "h": 368
            },
            {
              "type": "levelCard",
              "lockedImage": "https://img.onlywnn.cn/figma/h_70aef182.png",
              "position": {
                "x": 196,
                "y": 147
              },
              "w": 330,
              "h": 368
            },
            {
              "type": "levelCard",
              "lockedImage": "https://img.onlywnn.cn/figma/h_61c26d1d.png",
              "position": {
                "x": 40,
                "y": 316
              },
              "w": 342,
              "h": 390
            }
          ]
        },
        {
          "type": "collectCard",
          "bgImage": "",
          "total": 4,
          "collected": 1,
          "obtainedImage": "",
          "unobtainedImage": ""
        },
        {
          "type": "image",
          "image": "https://img.onlywnn.cn/figma/h_483ae3df.png"
        },
        {
          "type": "button",
          "image": "https://img.onlywnn.cn/figma/h_4dce23b9.png"
        }
      ]
    }
  },
  "$demo": {
    "presentation": {
      "version": 1,
      "mode": "fixed-canvas",
      "viewport": {
        "width": 375,
        "height": 812
      },
      "heightBehavior": "fixed",
      "preset": "custom",
      "source": "figma"
    }
  }
}

import { SvgaPlayer, SpinePlayer } from "@preview/sdk";

interface LevelCard {
  type?: string;
  lockedImage?: string;
  unlockedImage?: string;
  completedImage?: string;
  animation?: string;
  position?: { x: number; y: number };
  w?: number;
  h?: number;
}

interface Module {
  type: "image" | "button" | "participant" | "video" | "level" | "collectCard";
  image?: string;
  bgImage?: string;
  count?: number;
  videoBg?: string;
  video?: { url: string; poster?: string };
  guide?: { kind: "spine"; version: 1; assetId: string };
  levels?: LevelCard[];
  total?: number;
  collected?: number;
  obtainedImage?: string;
  unobtainedImage?: string;
}

interface DemoProps {
  bgm: string;
  navColor: string;
  modules: Module[];
}

/* 参与人数模块：背景图可配置，UI 控件样式固定 */
function ParticipantModule({ bgImage, count }: { bgImage?: string; count?: number }) {
  return (
    <div
      style={{
        alignSelf: "stretch",
        height: 45,
        flexShrink: 0,
        position: "relative",
        overflow: "hidden",
      }}
    >
      {bgImage ? (
        <img
          src={bgImage}
          alt="参与人数组件背景图"
          style={{ position: "absolute", left: 0, top: 0, width: 375, height: 45, objectFit: "cover" }}
        />
      ) : (
        <div style={{ position: "absolute", left: 0, top: 0, width: 375, height: 45, background: "#F0F0F0" }} />
      )}
      <div
        style={{
          position: "absolute",
          left: 105,
          top: 7,
          width: 165,
          height: 30,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: 6,
        }}
      >
        <span style={{ fontSize: 13, fontWeight: 700, color: "#404040", fontFamily: "PingFang SC" }}>
          参与人数
        </span>
        <span style={{ fontSize: 13, fontWeight: 700, color: "#FF9045", fontFamily: "PingFang SC" }}>
          {count ?? 0}
        </span>
      </div>
    </div>
  );
}

/* 视频模块：视频背景图 + 封面(poster) + 文件(url) */
function VideoModule({ videoBg, video }: { videoBg?: string; video?: { url: string; poster?: string } }) {
  const hasSrc = !!video?.url;
  return (
    <div
      style={{
        alignSelf: "stretch",
        height: 211,
        flexShrink: 0,
        position: "relative",
        background: "#DBDBDB",
        overflow: "hidden",
      }}
    >
      {videoBg ? (
        <img
          src={videoBg}
          alt="视频背景图"
          style={{ position: "absolute", left: 0, top: 0, width: 375, height: 211, objectFit: "cover" }}
        />
      ) : (
        <div
          style={{
            position: "absolute",
            left: 21,
            top: 11,
            width: 335,
            height: 188,
            background: "#F4F4F4",
            borderRadius: 10,
            border: "2px solid white",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            overflow: "hidden",
          }}
        >
          {hasSrc ? (
            <video
              src={video?.url}
              poster={video?.poster}
              controls
              style={{ width: "100%", height: "100%", objectFit: "cover", borderRadius: 8 }}
            />
          ) : (
            <>
              {video?.poster && (
                <img
                  src={video.poster}
                  alt="视频封面"
                  style={{ width: "100%", height: "100%", objectFit: "cover", borderRadius: 8 }}
                />
              )}
              <img
                src="https://img.onlywnn.cn/figma/h_f9f81d7b.png"
                alt="播放按钮"
                style={{ position: "absolute", left: 132, top: 59, width: 70, height: 70, objectFit: "cover" }}
              />
            </>
          )}
        </div>
      )}
    </div>
  );
}

/* 图片模块：任意数量、任意位置 */
function ImageModule({ image }: { image?: string }) {
  return (
    <img
      src={image}
      alt="图片组件"
      style={{ width: 375, height: "auto", display: "block", objectFit: "cover" }}
    />
  );
}

/* 集卡抽奖模块：背景图 / 卡片总数 / 已收集数量 / 已获得与未获得卡片图可配置，进度条与卡片样式固定 */
function CollectLotteryModule({
  bgImage,
  total,
  collected,
  obtainedImage,
  unobtainedImage,
}: {
  bgImage?: string;
  total?: number;
  collected?: number;
  obtainedImage?: string;
  unobtainedImage?: string;
}) {
  const cardTotal = Math.max(total ?? 4, 1);
  const gotCount = Math.min(Math.max(collected ?? 1, 0), cardTotal);
  const percent = (gotCount / cardTotal) * 100;
  return (
    <div
      style={{
        flexShrink: 0,
        position: "relative",
        background: "#DBDBDB",
        overflow: "hidden",
        display: "flex",
        flexDirection: "column",
        justifyContent: "flex-start",
        alignItems: "flex-start",
        gap: 10,
        paddingTop: 105,
        width: "100%",
        minHeight: 205,
      }}
    >
      {bgImage ? (
        <img
          src={bgImage}
          alt="集卡抽奖背景图"
          style={{ position: "absolute", left: 0, top: 0, width: 375, height: 205, objectFit: "cover" }}
        />
      ) : null}
      <div
        style={{
          position: "absolute",
          left: 20,
          top: 105,
          display: "flex",
          justifyContent: "flex-start",
          alignItems: "flex-start",
          gap: 8,
        }}
      >
        {Array.from({ length: cardTotal }).map((_, i) => {
          const obtained = i < gotCount;
          const cardImg = obtained ? obtainedImage : unobtainedImage;
          const label = obtained ? "已获得卡片" : "未获得卡片";
          return (
            <div
              key={i}
              style={{
                width: 98,
                height: 100,
                position: "relative",
                background: obtained ? "#F4F4F4" : "#C5C5C5",
                outline: `1px solid ${obtained ? "white" : "#B3B3B3"}`,
                outlineOffset: -1,
                overflow: "hidden",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              {cardImg ? (
                <img src={cardImg} alt={label} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
              ) : (
                <span
                  style={{
                    fontSize: 12,
                    fontWeight: 700,
                    color: obtained ? "rgba(0,0,0,0.2)" : "#E9E9E9",
                    fontFamily: "SF Pro Rounded",
                  }}
                >
                  {label}
                </span>
              )}
            </div>
          );
        })}
      </div>
      <div
        style={{
          position: "absolute",
          left: 20,
          top: 68,
          width: 339,
          padding: "2px 10px",
          background: "white",
          borderRadius: 999,
          display: "flex",
          alignItems: "center",
          gap: 7,
        }}
      >
        <div style={{ display: "flex", gap: 4 }}>
          <span style={{ fontSize: 12, fontWeight: 500, color: "#666666" }}>已收集</span>
          <span style={{ fontSize: 12, fontWeight: 500, color: "#FF9045" }}>{gotCount}</span>
        </div>
        <div style={{ flex: 1, height: 14, position: "relative" }}>
          <div
            style={{
              height: 11,
              width: "100%",
              position: "absolute",
              top: 1,
              background: "rgba(9,9,9,0.14)",
              borderRadius: 30,
            }}
          />
          <div
            style={{
              height: 11,
              width: `${percent}%`,
              position: "absolute",
              top: 0.5,
              background: "#FCDA00",
              borderRadius: 30,
            }}
          />
        </div>
        <div style={{ display: "flex", gap: 4 }}>
          <span style={{ fontSize: 12, fontWeight: 500, color: "#B2B2B2" }}>{cardTotal}</span>
        </div>
      </div>
    </div>
  );
}

/* 关卡图取图：已完成图 → 已解锁图 → 未解锁图，取第一个有值的图片 */
function resolveLevelImage(card: LevelCard): string | undefined {
  return card.completedImage || card.unlockedImage || card.lockedImage;
}

/* 关卡组件（可配置：背景图 + 关卡图(自定义图片/自由坐标/自定义尺寸) + 引导形象） */
function LevelModule({
  bgImage,
  guide,
  levels,
}: {
  bgImage?: string;
  guide?: { kind: "spine"; version: 1; assetId: string };
  levels?: LevelCard[];
}) {
  const cards = levels && levels.length > 0 ? levels : [];
  return (
    <div
      style={{
        alignSelf: "stretch",
        flexShrink: 0,
        position: "relative",
        background: "#DBDBDB",
        overflow: "hidden",
      }}
    >
      {/* 关卡背景图：以图片自然高度撑起组件高度（W=375） */}
      {bgImage ? (
        <img
          src={bgImage}
          alt="关卡背景图"
          style={{ display: "block", width: 375, objectFit: "cover" }}
        />
      ) : (
        <div style={{ width: 375, height: 656, background: "#DBDBDB" }} />
      )}

      {/* 关卡图：position 使用 1 倍像素，w/h 使用 2 倍值 */}
      {cards.map((card, i) => {
        const x = card.position?.x ?? 0;
        const y = card.position?.y ?? 0;
        const w = (card.w ?? 0) / 2;
        const h = (card.h ?? 0) / 2;
        const img = resolveLevelImage(card);
        const style = {
          position: "absolute" as const,
          left: x,
          top: y,
          width: w,
          height: h,
          objectFit: "cover" as const,
        };
        if (card.animation) {
          return (
            <div
              key={i}
              data-pos-key="levelCard"
              style={{ position: "absolute", left: x, top: y, width: w, height: h }}
            >
              <SvgaPlayer
                src={card.animation}
                loop
                autoplay
                style={{ width: "100%", height: "100%", objectFit: "cover" }}
                fallback={img ? <img src={img} alt={`关卡${i + 1}动画兜底`} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : null}
              />
            </div>
          );
        }
        if (!img) return null;
        return <img key={i} src={img} data-pos-key="levelCard" alt={`关卡${i + 1}`} style={style} />;
      })}

      {/* 闯关引导形象（Spine） */}
      {guide ? (
        <SpinePlayer
          src={guide}
          loop
          fit="contain"
          alignment="bottom"
          style={{ position: "absolute", left: 8, bottom: 20, width: 80, height: 130 }}
          fallback={null}
        />
      ) : null}
    </div>
  );
}

/* 按钮模块（图片可配置，整宽展示，高度 97px） */
function ButtonModule({ image }: { image?: string }) {
  const src = image || "https://img.onlywnn.cn/figma/h_4dce23b9.png";
  return (
    <img
      src={src}
      alt="按钮组件"
      style={{ width: 375, height: 97, objectFit: "cover", display: "block", flexShrink: 0 }}
    />
  );
}

/* 领课广告（固定特色区块） */
function AdModule() {
  return (
    <div style={{ alignSelf: "stretch", height: 236, flexShrink: 0, position: "relative" }}>
      <img
        src="https://img.onlywnn.cn/figma/h_e0d1c962.png"
        alt="图片组件"
        style={{ position: "absolute", left: 0, top: 0, width: 375, height: 236, objectFit: "cover" }}
      />
      <span
        style={{
          position: "absolute",
          left: 111,
          top: 89,
          opacity: 0.11,
          fontSize: 38.5,
          fontWeight: 700,
          fontFamily: "SF Pro Rounded",
          color: "black",
        }}
      >
        领课广告
      </span>
    </div>
  );
}

/* 我的作品（固定特色区块） */
function MyWorks() {
  return (
    <div
      style={{
        width: "100%",
        padding: "10px 16px",
        background: "#FFEAA3",
        display: "flex",
        flexDirection: "column",
        alignItems: "flex-start",
        gap: 10,
      }}
    >
      <div
        style={{
          width: 343,
          height: 226,
          position: "relative",
          overflow: "hidden",
          borderRadius: 25,
        }}
      >
        <img
          src="https://img.onlywnn.cn/figma/h_5d121fd1.png"
          alt="我的作品背景图"
          style={{ position: "absolute", left: 0, top: 0, width: 343, height: 226, objectFit: "cover" }}
        />
        <div
          style={{
            position: "absolute",
            left: 16,
            top: 70,
            width: 311,
