function renderModule(m: Module, key: number) {
  switch (m.type) {
    case "participant":
      return <ParticipantModule key={key} bgImage={m.bgImage} count={m.count} />;
    case "video":
      return <VideoModule key={key} videoBg={m.videoBg} video={m.video} />;
    case "image":
      return <ImageModule key={key} image={m.image} />;
    case "button":
      return <ButtonModule key={key} image={m.image} />;
    case "level":
      return (
        <LevelModule
          key={key}
          bgImage={m.bgImage}
          guide={m.guide}
          levels={m.levels}
        />
      );
    case "collectCard":
      return (
        <CollectLotteryModule
          key={key}
          bgImage={m.bgImage}
          total={m.total}
          collected={m.collected}
          obtainedImage={m.obtainedImage}
          unobtainedImage={m.unobtainedImage}
        />
      );
    default:
      return null;
  }
}

