edits.new_string:
/* 按钮模块（背景图整宽自适应高度，支持自定义地址 / 分享控件两种跳转类型） */
const CHANNEL_LABELS: Record<string, string> = {
  wechat: "微信",
  moments: "朋友圈",
  douyin: "抖音",
  xiaohongshu: "小红书",
};

function ButtonModule({
  image,
  linkType = "share",
  linkUrl,
  shareChannels,
}: {
  image?: string;
  linkType?: "custom" | "share";
  linkUrl?: string;
  shareChannels?: string[];
}) {
  const src = image || "https://img.onlywnn.cn/figma/h_4dce23b9.png";
  const channels = (shareChannels && shareChannels.length > 0 ? shareChannels : ["douyin"]).map(
    (c) => CHANNEL_LABELS[c] || c,
  );
  const alt = linkType === "share" ? `分享按钮：${channels.join("/")}` : "按钮组件";
  return (
    <a
      href={linkType === "custom" && linkUrl ? linkUrl : undefined}
      style={{ display: "block", width: 375, flexShrink: 0 }}
      aria-label={alt}
    >
      <img
        src={src}
        alt={alt}
        style={{ width: 375, height: "auto", display: "block", objectFit: "contain" }}
      />
      {linkType === "share" ? (
        <span
          style={{
            display: "block",
            textAlign: "center",
            fontSize: 11,
            color: "rgba(64,64,64,0.55)",
            padding: "2px 0 4px",
          }}
        >
          分享控件：{channels.join(" / ")}
        </span>
      ) : null}
    </a>
  );
}

