/* 关卡图取图：已完成图 → 已解锁图 → 未解锁图，取第一个有值的图片 */
function resolveLevelImage(card: LevelCard): string | undefined {
  return card.completedImage || card.unlockedImage || card.lockedImage;
}

/* 关卡组件（可配置：背景图 + 关卡图(自定义图片/自由坐标/自定义尺寸) + 引导形象） */
function LevelModule({
  bgImage,
  guide,
  levels,
}: {
  bgImage?: string;
  guide?: { kind: "spine"; version: 1; assetId: string };
  levels?: LevelCard[];
}) {
  const cards = levels && levels.length > 0 ? levels : [];
  return (
    <div
      style={{
        alignSelf: "stretch",
        flexShrink: 0,
        position: "relative",
        background: "#DBDBDB",
        overflow: "hidden",
      }}
    >
      {/* 关卡背景图：以图片自然高度撑起组件高度（W=375） */}
      {bgImage ? (
        <img
          src={bgImage}
          alt="关卡背景图"
          style={{ display: "block", width: 375, objectFit: "cover" }}
        />
      ) : (
        <div style={{ width: 375, height: 656, background: "#DBDBDB" }} />
      )}

      {/* 关卡图：position 使用 1 倍像素，w/h 使用 2 倍值 */}
      {cards.map((card, i) => {
        const x = card.position?.x ?? 0;
        const y = card.position?.y ?? 0;
        const w = (card.w ?? 0) / 2;
        const h = (card.h ?? 0) / 2;
        const img = resolveLevelImage(card);
        const style = {
          position: "absolute" as const,
          left: x,
          top: y,
          width: w,
          height: h,
          objectFit: "cover" as const,
        };
        if (card.animation) {
          return (
            <div
              key={i}
              data-pos-key="levelCard"
              style={{ position: "absolute", left: x, top: y, width: w, height: h }}
            >
              <SvgaPlayer
                src={card.animation}
                loop
                autoplay
                style={{ width: "100%", height: "100%", objectFit: "cover" }}
                fallback={img ? <img src={img} alt={`关卡${i + 1}动画兜底`} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : null}
              />
            </div>
          );
        }
        if (!img) return null;
        return <img key={i} src={img} data-pos-key="levelCard" alt={`关卡${i + 1}`} style={style} />;
      })}

      {/* 闯关引导形象（Spine） */}
      {guide ? (
        <SpinePlayer
          src={guide}
          loop
          fit="contain"
          alignment="bottom"
          style={{ position: "absolute", left: 8, bottom: 20, width: 80, height: 130 }}
          fallback={null}
        />
      ) : null}
    </div>
  );
}

/* 分享渠道文案映射（按钮跳转类型为分享控件时使用） */
const CHANNEL_LABELS: Record<string, string> = {
  wechat: "微信",
  moments: "朋友圈",
  douyin: "抖音",
  xiaohongshu: "小红书",
};

/* 按钮模块：整张按钮图（PNG/JPG/GIF，GIF 循环播放），宽 375 高度自适应；
   跳转类型支持自定义地址与分享控件，两种类型素材规范相同 */
function ButtonModule({
  image,
  linkType = "share",
  linkUrl,
  shareChannels,
}: {
  image?: string;
  linkType?: "custom" | "share";
  linkUrl?: string;
  shareChannels?: string[];
}) {
  const src = image || "https://img.onlywnn.cn/figma/h_4dce23b9.png";
  const channels = (shareChannels && shareChannels.length > 0 ? shareChannels : ["douyin"]).map(
    (c) => CHANNEL_LABELS[c] || c,
  );
  const isShare = linkType === "share";
  const alt = isShare ? `分享到${channels.join("、")}` : "按钮组件";
  const img = (
    <img
      src={src}
      alt={alt}
      style={{ width: 375, height: "auto", display: "block", objectFit: "contain", flexShrink: 0 }}
    />
  );
  return isShare || !linkUrl ? (
    <div style={{ width: 375, flexShrink: 0 }}>{img}</div>
  ) : (
    <a href={linkUrl} style={{ display: "block", width: 375, flexShrink: 0 }}>
      {img}
    </a>
  );
}

